StructuredText.Text:
// Tính lệnh start/stop theo mode
_bStartCmd := (stCmd.bManual AND stCmd.bMan_Start) OR (NOT stCmd.bManual AND stCmd.bAuto_Start);
_bStopCmd  := (stCmd.bManual AND stCmd.bMan_Stop)  OR (NOT stCmd.bManual AND stCmd.bAuto_Stop);

// EStop: FALSE = dừng khẩn
IF NOT stCmd.bEStop THEN
    _iState              := 99;
    stStatus.iFaultCode  := 99;
ELSE
    CASE _iState OF

        0: // Idle
            bDO_Run          := FALSE;
            rSpeedOut        := 0.0;
            stStatus.bRunning := FALSE;
            stStatus.bStopped := TRUE;
            IF _bStartCmd THEN
                _iState := 1;
                _tStartTimer(IN := FALSE, PT := tStartTimeout);
            END_IF;
            IF stCmd.bFaultReset THEN
                stStatus.iFaultCode := 0;
            END_IF;

        1: // Starting
            bDO_Run  := TRUE;
            rSpeedOut := 0.0;
            stStatus.bRunning := FALSE;
            stStatus.bStopped := FALSE;
            _tStartTimer(IN := TRUE, PT := tStartTimeout);
            IF bDI_RunFB THEN
                _iState := 2;
                _tStartTimer(IN := FALSE, PT := tStartTimeout);
            ELSIF _tStartTimer.Q THEN
                _iState             := 99;
                stStatus.iFaultCode := 2;
                _tStartTimer(IN := FALSE, PT := tStartTimeout);
            END_IF;

        2: // Running
            bDO_Run           := TRUE;
            stStatus.bRunning := TRUE;
            stStatus.bStopped := FALSE;
            // Tốc độ theo mode
            IF stCmd.bManual THEN
                rSpeedOut := stCmd.rMan_Speed;
            ELSE
                rSpeedOut := stCmd.rAuto_Speed;
            END_IF;
            // Clamp
            IF rSpeedOut < 0.0 THEN rSpeedOut := 0.0; END_IF;
            IF rSpeedOut > 100.0 THEN rSpeedOut := 100.0; END_IF;
            stStatus.rActSpeed := rSpeedOut;
            // Kiểm tra lỗi
            IF NOT bDI_RunFB THEN
                _iState             := 99;
                stStatus.iFaultCode := 3;
            ELSIF _bStopCmd THEN
                _iState := 3;
            END_IF;

        3: // Stopping
            bDO_Run           := FALSE;
            rSpeedOut         := 0.0;
            stStatus.bRunning := FALSE;
            stStatus.bStopped := FALSE;
            IF NOT bDI_RunFB THEN
                _iState := 0;
            END_IF;

        99: // Fault
            bDO_Run           := FALSE;
            rSpeedOut         := 0.0;
            stStatus.bRunning := FALSE;
            stStatus.bStopped := FALSE;
            stStatus.bFault   := TRUE;
            IF stCmd.bFaultReset THEN
                _iState             := 0;
                stStatus.bFault     := FALSE;
                stStatus.iFaultCode := 0;
            END_IF;

        ELSE
            _iState := 0;
    END_CASE;
END_IF;

stStatus.iState := _iState;
